from collections import Counter
from datetime import date


def summarize(items):
    c = Counter(items)
    top = c.most_common(1)[0][0] if items else None
    return {"total": len(items), "unique": len(c), "top": top}


def days_since(last_order, today):
    return (date.fromisoformat(today) - date.fromisoformat(last_order)).days

