def parse_line(line):
    parts = [p.strip() for p in line.split(",")]
    if len(parts) != 4:
        return None
    name, item, qty, price = parts
    try:
        return name, item, int(qty), int(price)
    except ValueError:
        return None


def spend_by_customer(lines):
    totals = {}
    for line in lines:
        row = parse_line(line)
        if row is None:
            continue
        name, item, qty, price = row
        totals[name] = totals.get(name, 0) + qty * price
    return totals

