import numpy as np


def weighted_score(scores, weights):
    if len(scores) != len(weights):
        raise ValueError("scores and weights must have the same length")
    return float(np.dot(np.array(scores, dtype=float), np.array(weights, dtype=float)))


def column_means(table):
    means = np.array(table, dtype=float).mean(axis=0)
    return [round(float(m), 2) for m in means]

