code.solution:
def row_revenue(row):
    try:
        return int(row["qty"]) * int(row["price"])
    except (ValueError, KeyError, TypeError):
        return None


def revenue_by(sales, field):
    totals = {}
    for row in sales:
        rev = row_revenue(row)
        if rev is None:
            continue
        totals[row[field]] = totals.get(row[field], 0) + rev
    return totals


def revenue_by_category(sales):
    return revenue_by(sales, "category")


def top_product(sales):
    by_product = revenue_by(sales, "product")
    if not by_product:
        return None
    return max(by_product, key=by_product.get)


def monthly_report(sales):
    months = {}
    bad = 0
    for row in sales:
        rev = row_revenue(row)
        if rev is None:
            bad += 1
            continue
        m = row["date"][:7]
        months[m] = months.get(m, 0) + rev
    return {"months": months, "bad_rows": bad}
